// The MCP app's game catalog, generated by `npm run manifests` (scripts/manifests.ts) from
// games/<slug>/game.json, apps/site/BUILD_IMPORTS.json and approved community games.
// Paths are site paths ("/game/tuck-pop"); the server joins them with SITE_ORIGIN.

export type Embed = 'inline' | 'fullscreen' | 'site';

export interface CatalogGame {
  slug: string;
  title: string;
  tagline: string;
  /** The listing's short description. */
  pitch: string;
  minAge: number;
  ageRange: string;
  genres: string[];
  tags: string[];
  devices: string[];
  controls: string[];
  orientation: 'any' | 'landscape' | 'portrait';
  requirements: string[];
  /** The whole game ("About 6 hours of story"). */
  playTime: string;
  /** One sitting, [shortest, longest] minutes; absent for community games, which don't declare it. */
  sessionMinutes?: [number,number];
  moods: string[];
  /** How it plays in assistants. Community games are always "site": they live on their own origins. */
  embed: Embed;
  contentNotes: string;
  quickStart: string[];
  version: string;
  accentColor: string;
  /** The game's page on the website. */
  page: string;
  cover: string;
  /** Title logo (first-party games only). */
  logo?: string;
  /** The verified single-file build, for games that play in assistants (embed inline or fullscreen). */
  build?: { path: string; bytes: number; sha256: string };
  /** Approved community games: the creator's nickname. */
  community?: { handle: string };
}

export interface Catalog { games: CatalogGame[] }
